    "schemaSql": "\nCREATE TABLE ad_events (\n  event_id INT PRIMARY KEY,\n  ad_id INT,\n  ad_category VARCHAR(50),\n  event_type VARCHAR(20),\n  event_time TIMESTAMP\n);\n\nINSERT INTO ad_events VALUES\n(1, 101, 'mobile', 'impression', '2024-07-02 10:15:00'),\n(2, 101, 'mobile', 'click', '2024-07-02 10:15:05'),\n(3, 101, 'mobile', 'impression', '2024-07-02 11:20:00'),\n(4, 102, 'desktop', 'impression', '2024-07-03 12:00:00'),\n(5, 102, 'desktop', 'impression', '2024-07-03 12:05:00'),\n(6, 102, 'desktop', 'click', '2024-07-03 12:05:10'),\n(7, 103, 'tablet', 'impression', '2024-07-04 09:30:00'),\n(8, 103, 'tablet', 'impression', '2024-07-04 09:45:00'),\n(9, 104, 'smart_tv', 'impression', '2024-07-05 14:00:00'),\n(10, 105, 'mobile', 'impression', '2024-06-30 23:59:00'); -- Excluded (June)\n",
