    "schemaSql": "\nCREATE TABLE inventory (\n  product_id INT PRIMARY KEY,\n  product_name VARCHAR(100),\n  current_stock INT,\n  daily_sales_velocity INT,\n  lead_time_days INT,\n  safety_stock INT\n);\n\nINSERT INTO inventory VALUES\n(101, 'SKU-Alpha', 45, 20, 3, 25),  -- ROP: (20*3)+25 = 85. Stock 45 < 85 -> Need 40\n(102, 'SKU-Bravo', 110, 15, 2, 20), -- ROP: (15*2)+20 = 50. Stock 110 >= 50 -> OK\n(103, 'SKU-Charlie', 15, 30, 2, 40),-- ROP: (30*2)+40 = 100. Stock 15 < 100 -> Need 85\n(104, 'SKU-Delta', 70, 10, 5, 30),  -- ROP: (10*5)+30 = 80. Stock 70 < 80 -> Need 10\n(105, 'SKU-Echo', 150, 25, 2, 30);  -- ROP: (25*2)+30 = 80. Stock 150 >= 80 -> OK\n",
    "starterSql": "-- Costco: Identify inventory items below reorder point\n-- Output: product_id, product_name, current_stock, reorder_point, units_to_order\nSELECT\n  -- Your code here\nFROM inventory;\n",
    "referenceSql": "WITH calc AS (\n  SELECT \n    product_id,\n    product_name,\n    current_stock,\n    (daily_sales_velocity * lead_time_days) + safety_stock AS reorder_point\n  FROM inventory\n)\nSELECT \n  product_id,\n  product_name,\n  current_stock,\n  reorder_point,\n  (reorder_point - current_stock) AS units_to_order\nFROM calc\nWHERE current_stock < reorder_point\nORDER BY units_to_order DESC, product_id ASC;",
