    "schemaSql": "\nCREATE TABLE transactions (\n  id INT PRIMARY KEY,\n  enterprise_client_id INT,\n  amount NUMERIC,\n  status VARCHAR(20)\n);\n\nINSERT INTO transactions VALUES\n(1, 101, 600.00, 'completed'),\n(2, 101, 800.00, 'completed'),  -- Total 1400, count 2 -> Qualifies if thresh <= 1000\n(3, 101, 200.00, 'failed'),\n(4, 102, 3500.00, 'completed'), -- Total 3500, count 1 -> Excluded (needs >= 2)\n(5, 103, 1200.00, 'completed'),\n(6, 103, 900.00, 'completed'),\n(7, 103, 1500.00, 'completed'), -- Total 3600, count 3 -> Qualifies\n(8, 104, 50.00, 'completed'),\n(9, 104, 75.00, 'completed');   -- Total 125, count 2 -> Excluded (volume too low)\n",
    "starterSql": "-- Adyen: Filter enterprise_client accounts by count >= 2 and total volume > 3000\n-- Output: enterprise_client_id, transaction_count, total_volume\nSELECT\n  -- Your code here\nFROM transactions;\n",
    "referenceSql": "SELECT \n  enterprise_client_id,\n  COUNT(*) AS transaction_count,\n  ROUND(SUM(amount), 2) AS total_volume\nFROM transactions\nWHERE status = 'completed'\nGROUP BY enterprise_client_id\nHAVING COUNT(*) >= 2 AND SUM(amount) > 3000\nORDER BY total_volume DESC, enterprise_client_id ASC;",
    "expectedColumns": [
      "enterprise_client_id",
      "transaction_count",
      "total_volume"
    ],
    "hints": [
      "Filter for `status = 'completed'` in the WHERE clause.",
      "Apply `HAVING COUNT(*) >= 2 AND SUM(amount) > 3000` after GROUP BY.",
      "Sort by `total_volume` DESC, then account id ASC."
    ],
    "explanation": "### WHERE vs HAVING\nA fundamental interview distinction: `WHERE` filters individual rows before grouping, whereas `HAVING` filters aggregated cohorts after grouping."
