    "schemaSql": "\nCREATE TABLE deals (\n  id INT PRIMARY KEY,\n  close_date DATE,\n  amount NUMERIC\n);\n\nINSERT INTO deals VALUES\n(1, '2024-11-19', 150.00), -- Excluded (Before)\n(2, '2024-11-20', 250.00),\n(3, '2024-11-20', 350.50),\n(4, '2024-11-21', 500.00),\n(5, '2024-11-22', 420.00),\n(6, '2024-11-25', 1200.00),\n(7, '2024-11-26', 80.00);   -- Excluded (After)\n",
