    "starterSql": "-- Netflix: Aggregate Holiday Premiere Stream Starts daily between 2024-11-20 and 2024-11-25\n-- Output: event_date, total_events, total_amount\nSELECT\n  -- Your code here\nFROM streams;\n",
    "referenceSql": "SELECT \n  stream_date AS event_date,\n  COUNT(*) AS total_events,\n  ROUND(SUM(amount), 2) AS total_amount\nFROM streams\nWHERE stream_date BETWEEN '2024-11-20' AND '2024-11-25'\nGROUP BY stream_date\nORDER BY event_date ASC;",
