    "schemaSql": "\nCREATE TABLE departments (\n  id INT PRIMARY KEY,\n  name VARCHAR(50)\n);\n\nCREATE TABLE employees (\n  id INT PRIMARY KEY,\n  department_id INT,\n  name VARCHAR(50),\n  salary INT\n);\n\nINSERT INTO departments VALUES\n(1, 'Group Alpha'),\n(2, 'Group Beta'),\n(3, 'Group Gamma');\n\nINSERT INTO employees VALUES\n(1, 1, 'Entity 1', 165000),\n(2, 1, 'Entity 2', 155000),\n(3, 1, 'Entity 3', 165000), -- Ties with Entity 1 for rank 1\n(4, 1, 'Entity 4', 140000),\n(5, 2, 'Entity 5', 95000),\n(6, 2, 'Entity 6', 95000),\n(7, 2, 'Entity 7', 85000),\n(8, 3, 'Entity 8', 110000),\n(9, 3, 'Entity 9', 115000),\n(10, 3, 'Entity 10', 115000);\n",
    "starterSql": "-- Amazon: Find top 2 employees per department using DENSE_RANK()\n-- Output: department_name, employee_name, salary, rnk\nWITH ranked AS (\n  -- Your code here\n)\nSELECT * FROM ranked;\n",
    "referenceSql": "WITH ranked AS (\n  SELECT \n    g.name AS department_name,\n    i.name AS employee_name,\n    i.salary,\n    DENSE_RANK() OVER (\n      PARTITION BY i.department_id \n      ORDER BY i.salary DESC\n    ) AS rnk\n  FROM employees i\n  JOIN departments g ON i.department_id = g.id\n)\nSELECT \n  department_name,\n  employee_name,\n  salary,\n  rnk\nFROM ranked\nWHERE rnk <= 2\nORDER BY department_name ASC, salary DESC, employee_name ASC;",
