    "schemaSql": "\nCREATE TABLE employees (\n  id INT PRIMARY KEY,\n  name VARCHAR(50),\n  manager_id INT\n);\n\nINSERT INTO employees VALUES\n(1, 'Sundar Pichai', NULL),       -- Level 1 (CEO)\n(2, 'EVP Sarah Johnson', 1),        -- Level 2\n(3, 'SVP David Miller', 1),         -- Level 2\n(4, 'VP Michael Chang', 2),         -- Level 3\n(5, 'Director Elena Rostova', 4),   -- Level 4\n(6, 'Staff Engineer Alex Wong', 5); -- Level 5\n",
    "starterSql": "-- Google: Traverse employee hierarchy using WITH RECURSIVE\n-- Output: employee_id, employee_name, manager_id, hierarchy_level\nWITH RECURSIVE org_tree AS (\n  -- Your code here\n)\nSELECT * FROM org_tree;\n",
    "referenceSql": "WITH RECURSIVE org_tree AS (\n  -- Anchor member: CEO\n  SELECT \n    id AS employee_id,\n    name AS employee_name,\n    manager_id,\n    1 AS hierarchy_level\n  FROM employees\n  WHERE manager_id IS NULL\n\n  UNION ALL\n\n  -- Recursive member\n  SELECT \n    e.id AS employee_id,\n    e.name AS employee_name,\n    e.manager_id,\n    ot.hierarchy_level + 1 AS hierarchy_level\n  FROM employees e\n  JOIN org_tree ot ON e.manager_id = ot.employee_id\n)\nSELECT \n  employee_id,\n  employee_name,\n  manager_id,\n  hierarchy_level\nFROM org_tree\nORDER BY hierarchy_level ASC, employee_id ASC;",
